export const getSkinDefinition = (skinId?: string): SkinDefinition => {
  if (!skinId) return ALL_SCIENCE_SKINS[19]; // default classic_chemist
  const resolvedId = SKIN_ALIASES[skinId] || skinId;
  const found = ALL_SCIENCE_SKINS.find(s => s.id === resolvedId || s.id === skinId);
  return found || ALL_SCIENCE_SKINS[19];
};
